const pptxgen = require("pptxgenjs");

const slideConfig = { type: "cover", index: 1, title: "Measuring AI Ability to Complete Long Software Tasks" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Accent bar top
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: theme.accent } });

  // Main title
  slide.addText("Measuring AI Ability to\nComplete Long Software Tasks", {
    x: 0.7, y: 1.0, w: 8.6, h: 1.8,
    fontSize: 38, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left", lineSpacingMultiple: 1.1
  });

  // Headline finding - accent pill
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.7, y: 3.0, w: 7.5, h: 0.55, fill: { color: theme.secondary }, rectRadius: 0.05
  });
  slide.addText("50% Task-Completion Time Horizon Doubling Every ~7 Months", {
    x: 0.9, y: 3.0, w: 7.3, h: 0.55,
    fontSize: 18, fontFace: "Calibri", color: theme.accent, bold: true, align: "left", valign: "middle"
  });

  // Authors & source
  slide.addText("Thomas Kwa, Ben West, Joel Becker et al.  —  METR (Model Evaluation & Threat Research)", {
    x: 0.7, y: 3.85, w: 8.6, h: 0.35,
    fontSize: 13, fontFace: "Calibri", color: theme.light, align: "left"
  });
  slide.addText("arxiv.org/abs/2503.14499  •  March 2025", {
    x: 0.7, y: 4.2, w: 8.6, h: 0.35,
    fontSize: 12, fontFace: "Calibri", color: theme.accent, align: "left"
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.565, w: 10, h: 0.06, fill: { color: theme.accent } });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "FFFFFF" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

