const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 4, title: "Exponential Trend Since 2019" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText("AI Task Horizon: 2 Seconds (GPT-2) to ~2 Hours (o3) in 6 Years", {
    x: 0.5, y: 0.2, w: 9, h: 0.55,
    fontSize: 24, fontFace: "Georgia", color: theme.primary, bold: true, align: "left", margin: 0, fit: "shrink"
  });

  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 0.8, w: 2.5, h: 0.04, fill: { color: theme.accent } });

  // Figure 1 - main chart image
  slide.addImage({ path: "./imgs/figure_1.jpg", x: 0.3, y: 0.95, w: 6.2, h: 4.2, sizing: { type: "contain", w: 6.2, h: 4.2 } });

  // Key stats panel on right
  slide.addShape(pres.shapes.RECTANGLE, { x: 6.7, y: 1.0, w: 3.0, h: 4.2, fill: { color: "F5F9F9" } });

  // Doubling time callout
  slide.addText("~207 days", {
    x: 6.8, y: 1.15, w: 2.8, h: 0.6,
    fontSize: 32, fontFace: "Georgia", color: theme.secondary, bold: true, align: "center", valign: "middle"
  });
  slide.addText("doubling time (~7 months)", {
    x: 6.8, y: 1.7, w: 2.8, h: 0.35,
    fontSize: 12, fontFace: "Calibri", color: theme.primary, align: "center"
  });

  // R² callout
  slide.addShape(pres.shapes.RECTANGLE, { x: 7.1, y: 2.2, w: 2.2, h: 0.04, fill: { color: theme.accent } });
  slide.addText("R² = 0.97", {
    x: 6.8, y: 2.35, w: 2.8, h: 0.5,
    fontSize: 28, fontFace: "Georgia", color: theme.light, bold: true, align: "center", valign: "middle"
  });
  slide.addText("over 6 years of model releases", {
    x: 6.8, y: 2.8, w: 2.8, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: theme.primary, align: "center"
  });

  // Model milestones
  slide.addShape(pres.shapes.RECTANGLE, { x: 7.1, y: 3.25, w: 2.2, h: 0.04, fill: { color: theme.accent } });

  const milestones = [
    { model: "GPT-2 (2019)", time: "~2 seconds" },
    { model: "GPT-4 (2023)", time: "~5 minutes" },
    { model: "o3 (2025)", time: "~1 hr 50 min" }
  ];

  milestones.forEach((m, i) => {
    const y = 3.45 + i * 0.5;
