    slide.addText(m.time, { x: 6.9, y: y + 0.2, w: 2.7, h: 0.25, fontSize: 11, fontFace: "Calibri", color: theme.secondary, align: "left", margin: 0 });
  });

  // Note
  slide.addText("2023–2025 growth rate ~20% faster than overall trend", {
    x: 0.5, y: 5.2, w: 5, h: 0.3, fontSize: 10, fontFace: "Calibri", color: "888888", align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("4", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
