const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 6, title: "Drivers of Progress" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText("Reasoning, Tool Use, and Error Recovery Drive Growth", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 26, fontFace: "Georgia", color: theme.primary, bold: true, align: "left", margin: 0, fit: "shrink"
  });

  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 0.85, w: 2.5, h: 0.04, fill: { color: theme.accent } });

  // 4 driver cards in 2x2 grid
  const drivers = [
    { title: "Improved Logical Reasoning", desc: "Models demonstrate increasingly sophisticated multi-step reasoning chains, enabling them to decompose complex problems." },
    { title: "Better Tool Use", desc: "Effective use of code execution, file manipulation, and external tools to complete software tasks autonomously." },
    { title: "Reliability & Self-Awareness", desc: "Greater consistency in task execution with improved ability to recognize limitations and uncertainty." },
    { title: "Error Recovery & Adaptation", desc: "Ability to detect mistakes, adjust strategies mid-task, and recover from failures without human intervention." }
  ];

  const cardW = 4.2;
  const cardH = 1.6;
  const positions = [
    { x: 0.5, y: 1.1 }, { x: 5.3, y: 1.1 },
    { x: 0.5, y: 2.85 }, { x: 5.3, y: 2.85 }
  ];

  drivers.forEach((d, i) => {
    const p = positions[i];
    // Card background
    slide.addShape(pres.shapes.RECTANGLE, { x: p.x, y: p.y, w: cardW, h: cardH, fill: { color: "F5F9F9" } });
    // Accent left bar
    slide.addShape(pres.shapes.RECTANGLE, { x: p.x, y: p.y, w: 0.06, h: cardH, fill: { color: theme.secondary } });
    // Title
    slide.addText(d.title, { x: p.x + 0.25, y: p.y + 0.15, w: cardW - 0.4, h: 0.35, fontSize: 15, fontFace: "Georgia", color: theme.primary, bold: true, align: "left", margin: 0 });
    // Description
    slide.addText(d.desc, { x: p.x + 0.25, y: p.y + 0.55, w: cardW - 0.4, h: 0.9, fontSize: 12, fontFace: "Calibri", color: "444444", align: "left", valign: "top", margin: 0 });
