const pptxgen = require("pptxgenjs");

const slideConfig = { type: "content", index: 7, title: "Extrapolation and Forecasts" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText("Extrapolation: Month-Long Task Automation by 2028–2031", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 26, fontFace: "Georgia", color: theme.primary, bold: true, align: "left", margin: 0, fit: "shrink"
  });

  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 0.85, w: 2.5, h: 0.04, fill: { color: theme.accent } });

  // Timeline visualization
  // Background bar
  slide.addShape(pres.shapes.RECTANGLE, { x: 0.8, y: 1.5, w: 8.4, h: 0.12, fill: { color: theme.secondary, transparency: 70 } });

  // Timeline points
  const timepoints = [
    { x: 1.0, label: "2019", sub: "GPT-2\n~2 sec", color: theme.secondary },
    { x: 2.8, label: "2023", sub: "GPT-4\n~5 min", color: theme.secondary },
    { x: 4.6, label: "2025", sub: "o3\n~2 hrs", color: theme.light },
    { x: 6.4, label: "2028", sub: "Projected\n~1 month?", color: theme.accent },
    { x: 8.2, label: "2031", sub: "Upper\nbound", color: theme.accent }
  ];

  timepoints.forEach((t) => {
    slide.addShape(pres.shapes.OVAL, { x: t.x, y: 1.38, w: 0.36, h: 0.36, fill: { color: t.color } });
    slide.addText(t.label, { x: t.x - 0.3, y: 1.8, w: 0.96, h: 0.3, fontSize: 12, fontFace: "Georgia", color: theme.primary, bold: true, align: "center" });
    slide.addText(t.sub, { x: t.x - 0.5, y: 2.08, w: 1.36, h: 0.55, fontSize: 10, fontFace: "Calibri", color: "666666", align: "center" });
  });

  // Dashed line separator for projection zone
  slide.addShape(pres.shapes.LINE, { x: 5.5, y: 1.2, w: 0, h: 1.5, line: { color: theme.accent, width: 1.5, dashType: "dash" } });
  slide.addText("PROJECTION", { x: 5.6, y: 1.15, w: 1.2, h: 0.25, fontSize: 8, fontFace: "Calibri", color: theme.accent, bold: true });

  // Key projection stats - cards
  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 3.0, w: 4.3, h: 1.8, fill: { color: "F5F9F9" } });
  slide.addText("167", {
    x: 0.7, y: 3.1, w: 2.5, h: 0.7,
    fontSize: 48, fontFace: "Georgia", color: theme.secondary, bold: true, align: "left", margin: 0
  });
  slide.addText("work hours (1 month)", {
    x: 0.7, y: 3.75, w: 3.8, h: 0.3,
    fontSize: 14, fontFace: "Calibri", color: theme.primary, align: "left", margin: 0
  });
  slide.addText("Projected 50% time horizon if the exponential trend\ncontinues at current pace. Reached between mid-2028\nand mid-2031 depending on rate assumptions.", {
    x: 0.7, y: 4.1, w: 3.8, h: 0.6,
    fontSize: 11, fontFace: "Calibri", color: "666666", align: "left", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 3.0, w: 4.3, h: 1.8, fill: { color: "F5F9F9" } });
  slide.addText("~20%", {
    x: 5.4, y: 3.1, w: 2.5, h: 0.7,
    fontSize: 48, fontFace: "Georgia", color: theme.light, bold: true, align: "left", margin: 0
  });
  slide.addText("faster recent growth", {
    x: 5.4, y: 3.75, w: 3.8, h: 0.3,
    fontSize: 14, fontFace: "Calibri", color: theme.primary, align: "left", margin: 0
  });
  slide.addText("2023–2025 growth rate is approximately 20% faster\nthan the overall 2019–2025 rate, suggesting possible\nacceleration of the trend.", {
    x: 5.4, y: 4.1, w: 3.8, h: 0.6,
    fontSize: 11, fontFace: "Calibri", color: "666666", align: "left", margin: 0
  });

  // Caveat
  slide.addText("Caveats: External validity uncertain; tasks may not represent average real-world intellectual labor. Trend could decelerate.", {
    x: 0.5, y: 4.95, w: 8.5, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: "888888", italic: true, align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("7", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "FFFFFF" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

