const pptxgen = require("pptxgenjs");

const slideConfig = { type: "summary", index: 8, title: "Takeaways" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText("Takeaways: Exponential Autonomous Capability Growth\nDemands Proactive Safety Governance", {
    x: 0.5, y: 0.25, w: 9, h: 0.9,
    fontSize: 24, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left", margin: 0, fit: "shrink"
  });

  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 2.5, h: 0.04, fill: { color: theme.accent } });

  // 5 takeaways
  const takeaways = [
    { num: "1", text: "50% time horizon is a robust, intuitive metric for tracking AI autonomy growth — R² = 0.97 over 6 years of model releases." },
    { num: "2", text: "Doubling every ~7 months with possible acceleration since 2024 — the 2023–2025 rate is ~20% faster than the overall trend." },
    { num: "3", text: "Current frontier at ~2 hours of human-equivalent autonomous work (o3), up from 2 seconds in 2019." },
    { num: "4", text: "External validity remains an open question — benchmark tasks may not perfectly represent real-world intellectual labor." },
    { num: "5", text: "Key limitations include poor performance on unstructured tasks and uncertain generalization to real-world job distributions." }
  ];

  takeaways.forEach((t, i) => {
    const y = 1.5 + i * 0.75;
    // Number badge
    slide.addShape(pres.shapes.OVAL, { x: 0.6, y: y + 0.05, w: 0.4, h: 0.4, fill: { color: theme.accent } });
    slide.addText(t.num, { x: 0.6, y: y + 0.05, w: 0.4, h: 0.4, fontSize: 16, fontFace: "Georgia", color: theme.primary, bold: true, align: "center", valign: "middle" });
    // Text
    slide.addText(t.text, { x: 1.2, y: y, w: 8.2, h: 0.55, fontSize: 13, fontFace: "Calibri", color: "FFFFFF", align: "left", valign: "middle" });
  });

  // Bottom accent
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.565, w: 10, h: 0.06, fill: { color: theme.accent } });

  // Source
  slide.addText("Kwa et al. (2025) — \"Measuring AI Ability to Complete Long Software Tasks\" — METR", {
    x: 0.5, y: 5.15, w: 6, h: 0.3, fontSize: 9, fontFace: "Calibri", color: theme.accent, align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("8", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "FFFFFF" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

