const pptxgen = require("pptxgenjs");
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "METR";
pres.title = "Measuring AI Ability to Complete Long Software Tasks: Time Horizon Doubling Every 7 Months";

const theme = {
  primary: "264653",
  secondary: "2a9d8f",
  accent: "e9c46a",
  light: "f4a261",
  bg: "FFFFFF"
};

for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, "0");
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: "./output/final_deck.pptx" }).then(() => {
  console.log("Presentation saved to ./output/final_deck.pptx");
});

